INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36811, 'Matthew 20:26', 'Matthew', 20, 26, 'خو په تاسو کې دې داسې نه وي. که په تاسو کې څوک غواړي چې لوی وګڼل شي، نو باید د نورو خدمتګار شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_26.mp3', '', 1761754199, 1761754199),
(36812, 'Matthew 20:27', 'Matthew', 20, 27, 'او هرڅوک چې غواړي د ټولو څخه اول شي باید د نورو خدمت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_27.mp3', '', 1761754199, 1761754199),
(36813, 'Matthew 20:28', 'Matthew', 20, 28, 'حتی د انسان زوی د دې دپاره نه دی راغلی چې خدمت یې وشي بلکې د نورو خدمت وکړي او خپل ژوند د ډېرو خلکو د خلاصون دپاره قربان کړي.» د دوو ړندو بینا کول (مرقوس ۱۰‏:‌۴۶‌‏-‌۵۲ او لوقا ۱۸‏:‌۳۵‌‏-‌۴۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_28.mp3', '', 1761754199, 1761754199),
(36814, 'Matthew 20:29', 'Matthew', 20, 29, 'کله چې عیسی او د هغه شاګردان د اریحا د ښار څخه تلل، نو ګڼ شمېر خلک ورپسې روان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_29.mp3', '', 1761754199, 1761754199),
(36815, 'Matthew 20:30', 'Matthew', 20, 30, 'د لارې په غاړه دوه ړانده ناست وو. کله چې هغوی خبر شول چې عیسی په دې لاره تېریږي، نو چیغې یې کړې: «ای ښاغلیه، ای د داود زویه! په مونږ رحم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_30.mp3', '', 1761754199, 1761754199),
(36816, 'Matthew 20:31', 'Matthew', 20, 31, 'خلکو هغوی ورټل او ورته ویې ویل چې غلي شئ. خو هغوی نورې هم چیغې ووهلې: «ای ښاغلیه، ای د داود زویه! په مونږ رحم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_31.mp3', '', 1761754199, 1761754199),
(36817, 'Matthew 20:32', 'Matthew', 20, 32, 'عیسی ودرېده او هغوی ته یې غږ وکړ او پوښتنه یې ترې وکړه: «زما نه څه غواړئ چې درته ویې کړم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_32.mp3', '', 1761754199, 1761754199),
(36818, 'Matthew 20:33', 'Matthew', 20, 33, 'هغوی ورته وویل: «ای ښاغلیه، غواړو چې سترګې مو بینا شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_33.mp3', '', 1761754199, 1761754199),
(36819, 'Matthew 20:34', 'Matthew', 20, 34, 'د عیسی زړه ورباندې وسوځېده او د هغوی په سترګو یې لاس کېښود او هغوی سمدلاسه بینا شول او په هغه پسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_34.mp3', '', 1761754199, 1761754199),
(36820, 'Matthew 17:1', 'Matthew', 17, 1, 'شپږ ورځې وروسته عیسی پطروس، یعقوب او د یعقوب ورور یوحنا د ځان سره واخیستل او یو لوړ غره ته یې بوتلل چې هلته یوازې اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_1.mp3', '', 1761754199, 1761754199),
(36821, 'Matthew 17:2', 'Matthew', 17, 2, 'د هغوی په مخکې د هغه څېره بدله شوه او مخ یې لکه د لمر په شان ځلېده او کالي یې د رڼا په شان سپین شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_2.mp3', '', 1761754199, 1761754199),
(36822, 'Matthew 17:3', 'Matthew', 17, 3, 'بیا ناڅاپه شاګردانو ته موسی او الیاس ښکاره شول چې د عیسی سره یې خبرې کولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_3.mp3', '', 1761754199, 1761754199),
(36823, 'Matthew 17:4', 'Matthew', 17, 4, 'نو پطروس عیسی ته وویل: «استاذه! څومره ښه ده چې مونږ دلته یو. که ته غواړې نو زه به دلته درې خېمې جوړې کړم، یوه تاته، یوه موسی ته او یوه الیاس ته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_4.mp3', '', 1761754199, 1761754199),
(36824, 'Matthew 17:5', 'Matthew', 17, 5, 'هغه لا خبرې کولې چې یوه سپینه ورېځ راخپره شوه او په هغوی باندې یې سیوری وکړ او د ورېځې څخه یو اواز راغی او ویل یې: «دا زما ګران زوی دی چې زه ترې خوشحاله یم. هغه ته غوږ ونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_5.mp3', '', 1761754199, 1761754199),
(36825, 'Matthew 17:6', 'Matthew', 17, 6, 'کله چې شاګردانو دا واورېدل، نو له ډېرې وېرې په ځمکه پړمخې پرېوتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_6.mp3', '', 1761754199, 1761754199),
(36826, 'Matthew 17:7', 'Matthew', 17, 7, 'بیا عیسی هغوی ته ورغی او په هغوی باندې یې لاس کېښود او ورته ویې ویل: «پاڅېږئ، مه وېرېږئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_7.mp3', '', 1761754199, 1761754199),
(36827, 'Matthew 17:8', 'Matthew', 17, 8, 'کله چې شاګردانو خپلې سترګې خلاصې کړې نو پرته له عیسی یې بل هېڅوک هلته ونه لیده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_8.mp3', '', 1761754199, 1761754199),
(36828, 'Matthew 17:9', 'Matthew', 17, 9, 'کله چې هغوی د غره څخه راښکته کېدل، نو عیسی هغوی ته امر وکړ: «څه چې مو لیدلي دي د هغو په هکله تر هغه وخته پورې چاته څه مه وایئ ترڅو پورې چې د انسان زوی بېرته د مړو ‎څخه راژوندی شوی نه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_9.mp3', '', 1761754199, 1761754199),
(36829, 'Matthew 17:10', 'Matthew', 17, 10, 'شاګردانو د عیسی نه پوښتنه وکړه: «بیا د شریعت عالمان ولې وایي چې لومړی باید الیاس راشي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_10.mp3', '', 1761754199, 1761754199),
(36830, 'Matthew 17:11', 'Matthew', 17, 11, 'عیسی ځواب ورکړ: «دا رښتیا ده چې لومړی به الیاس راځي او هرڅه به سم کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_11.mp3', '', 1761754199, 1761754199),
(36831, 'Matthew 17:12', 'Matthew', 17, 12, 'خو زه تاسو ته وایم چې الیاس لا پخوا راغلی دی، خو خلکو هغه ونه پېژانده او هرڅه چې دوی غوښتل د هغه سره یې وکړل. په همدې ډول به د انسان زوی هم د هغوی د لاسه وکړیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_12.mp3', '', 1761754199, 1761754199),
(36832, 'Matthew 17:13', 'Matthew', 17, 13, 'بیا شاګردان پوه شول چې هغه ورته د تعمید غسل ورکوونکي یحیی په هکله خبرې کولې. عیسی یو هلک ته چې پېریانو نیولی ؤ، شفا ورکوي (مرقوس ۹‏:‌۱۴‌‏-‌۲۹ او لوقا ۹‏:‌۳۷‌‏-‌۴۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_13.mp3', '', 1761754199, 1761754199),
(36833, 'Matthew 17:14', 'Matthew', 17, 14, 'کله چې عیسی او شاګردان یې بېرته خلکو ته راغلل، نو یو سړی عیسی ته راغی، د هغه په مخکې په ګونډو شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_14.mp3', '', 1761754199, 1761754199),
(36834, 'Matthew 17:15', 'Matthew', 17, 15, 'او ویې ویل: «ای ښاغلیه! زما په زوی باندې رحم وکړه. په هغه باندې میرګي راځي او داسې سختې حملې ورباندې راځي چې اکثره وختونه هغه په اور یا اوبو کې غورځیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_15.mp3', '', 1761754199, 1761754199),
(36835, 'Matthew 17:16', 'Matthew', 17, 16, 'هغه مې ستا شاګردانو ته راوست، خو ویې نه شو کولای چې هغه روغ کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_16.mp3', '', 1761754199, 1761754199),
(36836, 'Matthew 17:17', 'Matthew', 17, 17, 'عیسی په ځواب کې وویل: «ای د دې زمانې بې‌ایمانه او بې‌لارې خلکو، ترڅو پورې به زه ستاسو سره یم؟ ترڅو پورې به تاسو ته حوصله کوم؟ هغه هلک دلته ماته راولئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_17.mp3', '', 1761754199, 1761754199),
(36837, 'Matthew 17:18', 'Matthew', 17, 18, 'عیسی هغه پېري ته په کلکه امر وکړ، نو هغه د هلک څخه راووت او په هماغه ساعت هلک روغ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_18.mp3', '', 1761754199, 1761754199),
(36838, 'Matthew 17:19', 'Matthew', 17, 19, 'بیا شاګردان عیسی ته راغلل او کله چې هغوی یوازې وو نو پوښتنه یې ترې وکړه: «مونږ ولې ونه شو کولای چې هغه پېری وباسو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_19.mp3', '', 1761754199, 1761754199),
(36839, 'Matthew 17:20', 'Matthew', 17, 20, 'هغه ورته وویل: «ځکه چې ستاسو ایمان کمزوری دی. په یقین سره زه تاسو ته دا وایم چې که چېرې تاسو د شړشمو د دانې په اندازه ایمان هم ولرئ، نو کولای شئ دې غره ته ووایئ چې د دې ځای څخه هغه ځای ته لاړ شه، نو هغه به لاړ شي او هېڅ کار به ستاسو دپاره ناشونی نه وي. [', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_20.mp3', '', 1761754199, 1761754199),
(36840, 'Matthew 17:21', 'Matthew', 17, 21, 'دا ډول پېریان یوازې په دعا کولو او د روژې په نیولو سره کېدای شي وویستل شي.]» عیسی یوځل بیا د خپل مرګ په هکله خبرې کوي (مرقوس ۹‏:‌۳۰‌‏-‌۳۲ او لوقا ۹‏:‌۴۳‌‏-‌۴۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_21.mp3', '', 1761754199, 1761754199),
(36841, 'Matthew 17:22', 'Matthew', 17, 22, 'کله چې ټول شاګردان په جلیل کې سره یوځای شول نو عیسی ورته وویل: «د انسان زوی به خلکو ته په لاس ورکړل شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_22.mp3', '', 1761754199, 1761754199),
(36842, 'Matthew 17:23', 'Matthew', 17, 23, 'او هغوی به یې ووژني. خو په درېمه ورځ به بیا راژوندی شي.» د دې خبرې په اورېدلو شاګردان ډېر غمجن شول. د خدای د کور مالیه ورکول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_23.mp3', '', 1761754199, 1761754199),
(36843, 'Matthew 17:24', 'Matthew', 17, 24, 'کله چې عیسی او شاګردان یې کپرناحوم ته راغلل، نو د خدای د کور دپاره د مالیې راټولوونکي پطروس ته راغلل او پوښتنه یې ترې وکړه: «ایا ستا استاذ د خدای د کور مالیه ورکوي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_24.mp3', '', 1761754199, 1761754199),
(36844, 'Matthew 17:25', 'Matthew', 17, 25, 'پطروس وویل: «هو، هغه یې ورکوي.» کله چې پطروس کور ته لاړ، نو مخکې له دې چې څه ووایي، عیسی ورته وویل: «ای شمعونه، ته څه فکر کوې د نړۍ پاچاهان د چا څخه محصول او مالیه اخلي؟ د خپلو خلکو څخه یا د پردیو څخه؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_25.mp3', '', 1761754199, 1761754199),
(36845, 'Matthew 17:26', 'Matthew', 17, 26, 'پطروس ځواب ورکړ: «د پردیو څخه.» عیسی وویل: «نو بیا د دوی خپل خلک د مالیې ورکولو څخه معاف دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_26.mp3', '', 1761754199, 1761754199),
(36846, 'Matthew 17:27', 'Matthew', 17, 27, 'خو مونږ نه غواړو چې دا خلک خفه کړو. نو لاړ شه، په بحیرې کې چنګک واچوه او کوم ماهي چې دې اول ونیوه هغه راوباسه او د هغه خوله خلاصه کړه، نو د سپینو زرو یوه سکه به په کې پیدا کړې. هغه واخله او د هغې څخه زما او ستا دواړو مالیه ورکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew17_verse_27.mp3', '', 1761754199, 1761754199),
(36847, 'Luke 1:1', 'Luke', 1, 1, 'ښاغلی تیوفیلوسه: ډېرو خلکو کوښښ کړی دی ترڅو هغه پېښې بیان کړي چې زمونږ په منځ کې رامنځته شوې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_1.mp3', '', 1761754199, 1761754199),
(36848, 'Luke 1:2', 'Luke', 1, 2, 'هغوی هغه څه لیکلي دي چې مونږ ته د عیني شاهدانو او د خدای د کلام د خدمتګارانو له خوا رارسېدلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_2.mp3', '', 1761754199, 1761754199),
(36849, 'Luke 1:3', 'Luke', 1, 3, 'ښاغلی تیوفیلوسه، ما هم په خپل وار سره دا ټولې پېښې له پیل څخه په غور سره وڅېړلې، نو دا راته ښه ښکاره شوه چې هغه تاسو ته په ترتیب سره ولیکم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_3.mp3', '', 1761754199, 1761754199),
(36850, 'Luke 1:4', 'Luke', 1, 4, 'دا کار د دې دپاره کوم ترڅو ته د هغو ټولو شیانو په هکله چې ورڅخه خبر شوی یې، په حقیقت پوه شې. د یحیی د زېږېدنې په هکله پېشګويي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_4.mp3', '', 1761754199, 1761754199),
(36851, 'Luke 1:5', 'Luke', 1, 5, 'د یهودیې د پاچا هیرودیس په زمانه کې یو یهودي کاهن ؤ چې زکریا نومېده او د ابیا د ډلې څخه ؤ. د هغه ښځه الیزابت نومېدله او هغه هم د هارون کاهن د کورنۍ څخه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_5.mp3', '', 1761754199, 1761754199),
(36852, 'Luke 1:6', 'Luke', 1, 6, 'هغوی دواړه د خدای په نظر کې عادلان خلک وو او په پوره توګه یې د څښتن په ټولو قوانینو او حکمونو باندې عمل کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_6.mp3', '', 1761754199, 1761754199),
(36853, 'Luke 1:7', 'Luke', 1, 7, 'خو هغوی اولاد نه درلود، ځکه چې الیزابت شنډه وه او دواړه ډېر زاړه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_7.mp3', '', 1761754199, 1761754199),
(36854, 'Luke 1:8', 'Luke', 1, 8, 'کله چې د خدای په کور کې د خدمت وار د زکریا ډلې ته ورسېده، نو زکریا د کاهن په توګه په خپله وظیفه کې بوخت شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_8.mp3', '', 1761754199, 1761754199),
(36855, 'Luke 1:9', 'Luke', 1, 9, 'د کاهنانو د دود له مخې هغه د پچې په وسیله غوره شو، ترڅو د خدای کور ته ننوځي او خوشبویي وسوځوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_9.mp3', '', 1761754199, 1761754199),
(36856, 'Luke 1:10', 'Luke', 1, 10, 'د خوشبویۍ د سوځولو په وخت کې ګڼ شمېر عبادت کوونکي دباندې ولاړ وو او دعا یې کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_10.mp3', '', 1761754199, 1761754199),
(36857, 'Luke 1:11', 'Luke', 1, 11, 'په دې وخت کې د څښتن یوه فرښته زکریا ته ورښکاره شوه چې د قربانۍ د ځای ښي خواته چې خوشبویي په کې سوځېدله، ولاړه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_11.mp3', '', 1761754199, 1761754199),
(36858, 'Luke 1:12', 'Luke', 1, 12, 'کله چې زکریا هغه ولیدله، نو ټکان یې وخوړ او وېره ورباندې راغله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_12.mp3', '', 1761754199, 1761754199),
(36859, 'Luke 1:13', 'Luke', 1, 13, 'خو فرښتې هغه ته وویل: «ای زکریا، مه وېرېږه! ستا دعا قبوله شوې ده او ستا ښځه الیزابت به تاته یو زوی وزېږوي او ته به په هغه باندې یحیی نوم کېږدې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_13.mp3', '', 1761754199, 1761754199),
